import sys

def solve() -> None:
    data = sys.stdin.read().splitlines()
    if not data:
        return
    N = int(data[0])
    S = data[1].strip()
    left1 = [0] * N  # number of consecutive '1's immediately before index i
    for i in range(1, N):
        if S[i - 1] == '1':
            left1[i] = left1[i - 1] + 1
        else:
            left1[i] = 0

    right2 = [0] * N  # number of consecutive '2's immediately after index i
    for i in range(N - 2, -1, -1):
        if S[i + 1] == '2':
            right2[i] = right2[i + 1] + 1
        else:
            right2[i] = 0

    ans = 0
    for i, ch in enumerate(S):
        if ch != '/':
            continue
        L = left1[i]
        R = right2[i]
        total = L + 1 + R
        # ensure odd length
        if (L + R) % 2 == 1:
            total -= 1
        ans = max(ans, total)

    print(ans)

if __name__ == "__main__":
    solve()
