from typing import List
import re

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Group events by timestamp
        by_ts = {}
        for ev in events:
            t = int(ev[1])
            by_ts.setdefault(t, []).append(ev)

        # Prepare data structures
        offline = set()
        end_time = {}  # user -> timestamp when they come back online
        mentions = [0] * numberOfUsers

        # Process timestamps in order
        for t in sorted(by_ts.keys()):
            # 1. Process all users that should come back online at this time
            to_remove = [u for u, et in end_time.items() if et <= t]
            for u in to_remove:
                offline.remove(u)
                del end_time[u]

            # 2. Separate OFFLINE and MESSAGE events at this timestamp
            offs = [ev for ev in by_ts[t] if ev[0] == "OFFLINE"]
            msgs = [ev for ev in by_ts[t] if ev[0] == "MESSAGE"]

            # 3. Handle OFFLINE events first
            for ev in offs:
                uid = int(ev[2])
                offline.add(uid)
                end_time[uid] = t + 60

            # 4. Handle MESSAGE events
            for ev in msgs:
                tokens = ev[2].split()
                for token in tokens:
                    if token == "ALL":
                        for uid in range(numberOfUsers):
                            mentions[uid] += 1
                    elif token == "HERE":
                        for uid in range(numberOfUsers):
                            if uid not in offline:
                                mentions[uid] += 1
                    else:  # idX
                        m = re.match(r"id(\d+)", token)
                        if m:
                            uid = int(m.group(1))
                            mentions[uid] += 1

        return mentions
