from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # best_global[d] = longest subsequence seen so far with last absolute diff >= d
        best_global = [0] * 301   # differences are in [0, 300]
        best_len = 1              # at least one element subsequence

        for i in range(n):
            local = [0] * 301    # store best subsequence ending at i with each diff

            for j in range(i):
                d = abs(nums[i] - nums[j])
                val = best_global[d] + 1
                if val > local[d]:
                    local[d] = val

            # Update global bests and overall answer
            for d in range(301):
                if local[d] > best_global[d]:
                    best_global[d] = local[d]
                    if local[d] > best_len:
                        best_len = local[d]

        return best_len
